/// Manic MP: a stick crossing center produces two events from one HID report, a
/// deactivate of one direction and an activate of the other. They are different
/// keys, and a Dictionary flush delivered them in arbitrary order; "activate right"
/// before "deactivate left" left the stick reading center while it was held hard
/// over, until the next sample. Every kept sample now carries the sequence number
/// of its latest arrival, and the flush replays them in that order: for any two
/// inputs, their final events land in the order the controller produced them, so
/// a receiver that keeps last-write-wins state (the cores' stick positions) ends
/// where the controller is.
final class AnalogInputCoalescer {
    static let shared = AnalogInputCoalescer()

    private struct Key: Hashable {
        let controller: ObjectIdentifier
        let receiver: ObjectIdentifier
        let inputType: String
        let inputName: String
    }

    private struct Event {
        let controller: GameController
        let receiver: GameControllerReceiver
        let input: AnyInput
        var value: Double
        var isActivate: Bool
        /// Arrival order of the sample this event now carries.
        var sequence: UInt64
        /// When the first sample behind this event was queued (system uptime).
        let enqueuedAt: TimeInterval
        /// Samples replaced by a newer one before the flush ran.
        var collapsed: Int
    }

    private let lock = NSLock()
    private var pending: [Key: Event] = [:]
    private var scheduled = false
    private var nextSequence: UInt64 = 0

    private init() {}

    func enqueue(controller: GameController, receiver: GameControllerReceiver, input: Input, value: Double, isActivate: Bool) {
        let key = Key(
            controller: ObjectIdentifier(controller),
            receiver: ObjectIdentifier(receiver as AnyObject),
            inputType: input.type.rawValue,
            inputName: input.stringValue
        )
        lock.lock()
        nextSequence &+= 1
        if var event = pending[key] {
            event.value = value
            event.isActivate = isActivate
            event.sequence = nextSequence
            event.collapsed += 1
            pending[key] = event
        } else {
            pending[key] = Event(controller: controller, receiver: receiver, input: AnyInput(input), value: value, isActivate: isActivate,
                                 sequence: nextSequence, enqueuedAt: InputDiagnostics.now(), collapsed: 0)
        }
        let needsSchedule = !scheduled
        scheduled = true
        lock.unlock()
        if needsSchedule {
            DispatchQueue.main.async { [weak self] in
                self?.flush()
            }
        }
    }

    func cancelPending() {
        lock.lock()
        pending.removeAll(keepingCapacity: true)
        scheduled = false
        lock.unlock()
    }

    private func flush() {
        lock.lock()
        let events = pending.values.sorted { $0.sequence < $1.sequence }
        pending.removeAll(keepingCapacity: true)
        scheduled = false
        lock.unlock()
        if InputDiagnostics.shared.isEnabled {
            let now = InputDiagnostics.now()
            for event in events {
                InputDiagnostics.shared.noteFlushed(hop: now - event.enqueuedAt, collapsed: event.collapsed)
            }
        }
        for event in events {
            if event.isActivate {
                event.receiver.gameController(event.controller, didActivate: event.input, value: event.value)
            } else {
                event.receiver.gameController(event.controller, didDeactivate: event.input)
            }
        }
    }
}

/// Manic MP: input timing for the emulator session log, so a stick that "cuts out"
/// can be told apart as the controller going quiet, the framework delivering late,
/// or the main thread (where the cores run) taking the samples late.
///
/// Off unless the app starts it; every hook is one flag check when off. While on,
/// one line per connected controller and one for the analog coalescer go to `sink`
/// every second, from the HID queue:
///
///   pad "Name" p1: 240 callbacks, delivery latency avg 4.1 ms max 9.8 ms, longest gap while deflected 31 ms, stalest deflected sample 12 ms
///   coalescer: 180 flushes, hop to main avg 3.2 ms max 41.0 ms, 60 samples collapsed
