/// a stick was held out of its dead zone (a Bluetooth drop-out shows here); `stalest`
/// is how old the controller's last event was at the tick while a stick was held
/// (the controller stopped talking); `hop to main` is how long a sample waited for
/// the main thread, i.e. for the running emulator frame.
public final class InputDiagnostics {
    public static let shared = InputDiagnostics()

    /// Receives one finished line at a time, on the HID queue.
    public var sink: ((String) -> Void)?

    public private(set) var isEnabled = false

    private struct ControllerStats {
        var name: String
        var playerIndex: Int?
        var callbacks = 0
        var latencySum: TimeInterval = 0
        var latencyMax: TimeInterval = 0
        var latencySamples = 0
        var lastCallbackAt: TimeInterval?
        var longestGapDeflected: TimeInterval = 0
        var stalestDeflected: TimeInterval = 0
        var deflectedAxes = Set<String>()
    }

    private let lock = NSLock()
    private var controllers: [ObjectIdentifier: ControllerStats] = [:]
    private var flushes = 0
    private var hopSum: TimeInterval = 0
    private var hopMax: TimeInterval = 0
    private var hopSamples = 0
    private var collapsed = 0
    private var timer: DispatchSourceTimer?

    private init() {}

    /// Same clock as GCPhysicalInputProfile.lastEventTimestamp.
    static func now() -> TimeInterval {
        ProcessInfo.processInfo.systemUptime
    }

    public func start(sink: @escaping (String) -> Void) {
        lock.lock()
        self.sink = sink
        controllers.removeAll()
        resetCoalescerCountersUnlocked()
        isEnabled = true
        timer?.cancel()
        let timer = DispatchSource.makeTimerSource(queue: ExternalInputDispatch.queue)
        timer.schedule(deadline: .now() + 1, repeating: 1)
        timer.setEventHandler { [weak self] in self?.tick() }
        self.timer = timer
        lock.unlock()
        timer.resume()
    }

    public func stop() {
        lock.lock()
        isEnabled = false
        timer?.cancel()
        timer = nil
        sink = nil
        controllers.removeAll()
        lock.unlock()
    }

    /// A stick axis callback. `axis` names the axis (any stable string per axis),
    /// `deflected` whether its value is outside the dead zone.
    func noteAxis(controller: GCController, axis: String, deflected: Bool) {
        guard isEnabled else { return }
        note(controller: controller) { stats in
            if deflected {
                stats.deflectedAxes.insert(axis)
            } else {
                stats.deflectedAxes.remove(axis)
            }
        }
    }

    /// A button callback.
    func noteButton(controller: GCController) {
        guard isEnabled else { return }
        note(controller: controller) { _ in }
    }

    func noteFlushed(hop: TimeInterval, collapsed: Int) {
        lock.lock()
        flushes += 1
        hopSum += hop
        hopSamples += 1
        if hop > hopMax { hopMax = hop }
        self.collapsed += collapsed
        lock.unlock()
    }

    private func note(controller: GCController, _ update: (inout ControllerStats) -> Void) {
        let now = Self.now()
        let profile = controller.physicalInputProfile
        var latency: TimeInterval?
        if #available(iOS 17.0, tvOS 17.0, macOS 14.0, *) {
            latency = profile.lastEventLatency
        }
        lock.lock()
        var stats = controllers[ObjectIdentifier(controller)]
            ?? ControllerStats(name: controller.vendorName ?? "controller", playerIndex: Self.playerNumber(controller))
        stats.playerIndex = Self.playerNumber(controller)
        stats.callbacks += 1
        if let latency {
            stats.latencySum += latency
            stats.latencySamples += 1
            if latency > stats.latencyMax { stats.latencyMax = latency }
        }
        if let last = stats.lastCallbackAt, !stats.deflectedAxes.isEmpty {
            let gap = now - last
            if gap > stats.longestGapDeflected { stats.longestGapDeflected = gap }
        }
        stats.lastCallbackAt = now
        update(&stats)
        controllers[ObjectIdentifier(controller)] = stats
        lock.unlock()
    }

    private static func playerNumber(_ controller: GCController) -> Int? {
        switch controller.playerIndex {
        case .index1: return 1
        case .index2: return 2
        case .index3: return 3
        case .index4: return 4
        default: return nil
        }
    }

    private func resetCoalescerCountersUnlocked() {
        flushes = 0
        hopSum = 0
        hopMax = 0
        hopSamples = 0
        collapsed = 0
    }

    private static func ms(_ seconds: TimeInterval) -> String {
        String(format: "%.1f ms", seconds * 1000)
    }

    private func tick() {
        let now = Self.now()
        var lines: [String] = []
        lock.lock()
        guard isEnabled, let sink else { lock.unlock(); return }
        for controller in GCController.controllers() {
            let id = ObjectIdentifier(controller)
            var stats = controllers[id] ?? ControllerStats(name: controller.vendorName ?? "controller", playerIndex: Self.playerNumber(controller))
            if !stats.deflectedAxes.isEmpty {
                let staleness = now - controller.physicalInputProfile.lastEventTimestamp
                if staleness > stats.stalestDeflected { stats.stalestDeflected = staleness }
            }
            let player = stats.playerIndex.map { "p\($0)" } ?? "p?"
            let latency = stats.latencySamples > 0
                ? "delivery latency avg \(Self.ms(stats.latencySum / Double(stats.latencySamples))) max \(Self.ms(stats.latencyMax))"
                : "delivery latency n/a"
            lines.append("pad \"\(stats.name)\" \(player): \(stats.callbacks) callbacks, \(latency), longest gap while deflected \(Self.ms(stats.longestGapDeflected)), stalest deflected sample \(Self.ms(stats.stalestDeflected))\(stats.deflectedAxes.isEmpty ? "" : " [held]")")
            stats.callbacks = 0
            stats.latencySum = 0
            stats.latencyMax = 0
            stats.latencySamples = 0
            stats.longestGapDeflected = 0
            stats.stalestDeflected = 0
            controllers[id] = stats
        }
        let hop = hopSamples > 0
            ? "hop to main avg \(Self.ms(hopSum / Double(hopSamples))) max \(Self.ms(hopMax))"
            : "hop to main n/a"
        lines.append("coalescer: \(flushes) flushes, \(hop), \(collapsed) samples collapsed")
        resetCoalescerCountersUnlocked()
        lock.unlock()
        for line in lines {
            sink(line)
        }
    }
}
